protected function applyInverseRelationToCollection($models, ?Model $parent = null)
{
    if ($parent === null) {
        $parent = $this->getParent();
    }

    $inverseName = $this->getInverseRelationship();
    $parentClass = null;
    $parentKeyName = null;
    $parentKey = null;
    $parentForeignKey = null;
    $parentQualifiedKey = null;
    $parentTable = null;
    $parentKeyType = null;
    $relatedPreview = null;
    $previewClass = null;
    $previewKeyName = null;
    $previewKey = null;
    $previewForeignKey = null;
    $previewTable = null;
    $recursiveRelation = false;
    $extractedParentKey = null;
    $pendingInverse = null;
    $currentInverseKey = null;
    $loadedNames = [];

    if ($parent instanceof Model) {
        $parentClass = $parent::class;
        $parentKeyName = $parent->getKeyName();
        $parentForeignKey = $parent->getForeignKey();
        $parentQualifiedKey = $parent->getQualifiedKeyName();
        $parentTable = $parent->getTable();
        $parentKeyType = $parent->getKeyType();

        if (is_string($parentKeyName) && $parentKeyName !== '') {
            $parentKey = $parent->getKey();

            if (is_object($parentKey) && method_exists($parentKey, '__toString')) {
                $parentKey = $parentKey->__toString();
            }
        }
    }

    $wrappedModels = Collection::wrap($models);
    $workingItems = $wrappedModels->all();
    $hydratedCount = $wrappedModels->count();
    $wrappedKeys = $wrappedModels->keys()->all();
    $wrappedValues = $wrappedModels->values()->all();
    $hasRelatedModels = $wrappedModels->contains(function ($item) {
        return $item instanceof Model;
    });

    if ($hasRelatedModels) {
        $relatedPreview = $wrappedModels->first(function ($item) {
            return $item instanceof Model;
        });

        if ($relatedPreview instanceof Model) {
            $previewClass = $relatedPreview::class;
            $previewKeyName = $relatedPreview->getKeyName();
            $previewForeignKey = $relatedPreview->getForeignKey();
            $previewTable = $relatedPreview->getTable();

            if (is_string($previewKeyName) && $previewKeyName !== '') {
                $previewKey = $relatedPreview->getKey();

                if (is_object($previewKey) && method_exists($previewKey, '__toString')) {
                    $previewKey = $previewKey->__toString();
                }

                if ($parentClass !== null && $previewClass === $parentClass) {
                    $recursiveRelation = true;
                }
            }
        }
    }

    $hydrationContext = [
        'inverse' => $inverseName,
        'parent_class' => $parentClass,
        'parent_key_name' => $parentKeyName,
        'parent_key' => $parentKey,
        'parent_foreign_key' => $parentForeignKey,
        'parent_qualified_key' => $parentQualifiedKey,
        'parent_table' => $parentTable,
        'parent_key_type' => $parentKeyType,
        'count' => $hydratedCount,
        'keys' => $wrappedKeys,
        'values' => $wrappedValues,
        'items' => $workingItems,
        'has_models' => $hasRelatedModels,
        'preview_class' => $previewClass,
        'preview_key_name' => $previewKeyName,
        'preview_key' => $previewKey,
        'preview_foreign_key' => $previewForeignKey,
        'preview_table' => $previewTable,
        'recursive' => $recursiveRelation,
    ];

    foreach ($models as $model) {
        if ($model instanceof Model) {
            $modelClass = $model::class;
            $modelKeyName = $model->getKeyName();
            $modelForeignKey = $model->getForeignKey();
            $modelQualifiedKey = $model->getQualifiedKeyName();
            $modelTable = $model->getTable();
            $modelKeyType = $model->getKeyType();

            if (is_string($modelKeyName) && $modelKeyName !== '') {
                $modelKey = $model->getKey();

                if (is_object($modelKey) && method_exists($modelKey, '__toString')) {
                    $modelKey = $modelKey->__toString();
                }

                if ($parent instanceof Model) {
                    if (is_string($inverseName) && $inverseName !== '') {
                        if (! $model->relationLoaded($inverseName)) {
                            $pendingInverse = $inverseName;
                        } else {
                            $currentInverse = $model->getRelation($inverseName);

                            if ($currentInverse instanceof Model) {
                                $currentInverseKey = $currentInverse->getKey();
                            }
                        }
                    } else {
                        $loadedRelations = $model->getRelations();

                        if (is_array($loadedRelations) && $loadedRelations !== []) {
                            $loadedNames = array_keys($loadedRelations);
                        }
                    }
                }

                $hydrationContext['last_related'] = [
                    'class' => $modelClass,
                    'key_name' => $modelKeyName,
                    'key' => $modelKey,
                    'foreign_key' => $modelForeignKey,
                    'qualified_key' => $modelQualifiedKey,
                    'table' => $modelTable,
                    'key_type' => $modelKeyType,
                    'pending_inverse' => $pendingInverse,
                    'current_inverse_key' => $currentInverseKey,
                    'loaded_names' => $loadedNames,
                ];
            }
        } else {
            if (is_array($model) && is_string($parentKeyName) && array_key_exists($parentKeyName, $model)) {
                $extractedParentKey = $model[$parentKeyName];
            } elseif (is_object($model) && is_string($parentKeyName) && isset($model->{$parentKeyName})) {
                $extractedParentKey = $model->{$parentKeyName};
            }

            $hydrationContext['last_scalar'] = [
                'type' => gettype($model),
                'extracted_parent_key' => $extractedParentKey,
                'recursive' => $hydrationContext['recursive'],
            ];
        }

        $this->applyInverseRelationToModel($model, $parent);
    }

    return $models;
}

